mapper.select:
SELECT COUNT(*)
FROM op_community_databoard N


		AND SUB_CATEGORY = #{subCategory}


		AND CATEGORY_TEAM LIKE CONCAT('%', #{categoryTeam}, '%')



			AND SUBJECT LIKE CONCAT('%', #{query}, '%')


			AND CONTENT LIKE CONCAT('%', #{query}, '%')



		AND NOTICE_FLAG = #{noticeFlag}


		AND (VISIBLE_TYPE = #{visibleType} OR VISIBLE_TYPE = 1)


		AND DATE_FORMAT(N.CREATED_DATE,'%Y%m%d') BETWEEN #{startCreateDate} AND #{endCreateDate}

SELECT A.data_id, A.subject, A.url, A.category_team, crypto_dec('normal', A.user_name, '', 0) user_name, A.password, A.email, A.content, A.hits, A.board_code, A.sub_category, A.created_date, A.target_option, A.rel_option, A.notice_flag, A.visible_type, A.seller_select_flag, A.new_flag, A.use_yn FROM ( SELECT N.data_id, N.subject, N.url, N.category_team, N.user_name, N.password, N.email, N.content, N.hits, N.board_code, N.sub_category, N.created_date, N.target_option, N.rel_option, N.notice_flag, N.visible_type, N.seller_select_flag, CASE WHEN DATE_FORMAT(ADDDATE(STR_TO_DATE(N.created_date,'%Y%m%d%H%i%s'), INTERVAL 3 DAY),'%Y%m%d%H%i%s') >= THEN 'Y' ELSE 'N' END AS new_flag, use_yn FROM op_community_databoard N ) A
AND (VISIBLE_TYPE = #{visibleType} OR VISIBLE_TYPE = 1)
AND SUB_CATEGORY = #{subCategory}
AND CATEGORY_TEAM LIKE CONCAT('%', #{categoryTeam}, '%')
AND NOTICE_FLAG = #{noticeFlag}
AND SUBJECT LIKE CONCAT('%', #{query}, '%')
AND CONTENT LIKE CONCAT('%', #{query}, '%')
AND DATE_FORMAT(A.created_date,'%Y%m%d') BETWEEN #{startCreateDate} AND #{endCreateDate}
GROUP BY A.data_id ORDER BY A.notice_flag DESC, A.data_id DESC

mapper.update:
UPDATE op_community_databoard
SET HITS = HITS + 1
WHERE DATA_ID = #{value}

mapper.select:
SELECT DATA_ID, SUBJECT, CASE WHEN URL IS NULL OR URL = '' THEN CONCAT('/board/view/',DATA_ID) ELSE TRIM(URL) END AS URL , CASE WHEN URL IS NULL OR URL = '' THEN 0 ELSE 1 END AS URL_TYPE , CATEGORY_TEAM, TARGET_OPTION, REL_OPTION, SUB_CATEGORY, CREATED_DATE FROM (
SELECT * FROM ( SELECT DATA_ID, SUBJECT, URL, #{teamCode} AS CATEGORY_TEAM, TARGET_OPTION, REL_OPTION, SUB_CATEGORY, CREATED_DATE FROM op_community_databoard WHERE CATEGORY_TEAM LIKE CONCAT('%', #{teamCode}, '%') ORDER BY DATA_ID DESC LIMIT 5 ) T#{index}
) T

mapper.insert:
INSERT INTO op_community_databoard_file (
	DATA_FILE_ID
	, DATA_ID
	, FILE_NAME
	, FILE_TY
	, ORDERING
	, CREATED_DATE
	, ORG_FILE_NAME
) VALUES (
	#{dataFileId}
	, #{dataId}
	, #{fileName}
	, #{fileTy}
	, (SELECT IFNULL(MAX(ORDERING)+1, 1) FROM OP_DATA_BOARD_FILE WHERE DATA_ID = #{dataId})
	, 
	, #{orgFileName}
)
